package mz.co.aprendaacodar.enrollment.repository;import mz.co.aprendaacodar.enrollment.entity.CourseEnrollment;import mz.co.aprendaacodar.common.enums.Enums.EnrollmentStatus;import org.springframework.data.jpa.repository.JpaRepository;import java.util.*;
